INSERT OR REPLACE INTO diagnostics (id, service_order_id, descripcion, recomendaciones, creado_por, created_at) VALUES ('dia_3l_seed', 'ord_1048', 'Se realizó prueba de ruta y revisión en elevador. Se evidencia desgaste en los 4 amortiguadores (fuga de aceite en el delantero derecho), bujes de tijera delanteros con juego y bieletas con desgaste. La cremallera de dirección está en buen estado (se descartó la fuga que se sospechó inicialmente).', 'Reemplazar el juego de amortiguadores delanteros y traseros, cambiar bujes de tijera y bieletas. Realizar alineación y balanceo computerizada al terminar. No se requiere intervención de la cremallera.', 'usr_ana', '2026-10-26T19:00:00.000Z');
INSERT OR REPLACE INTO diagnostics (id, service_order_id, descripcion, recomendaciones, creado_por, created_at) VALUES ('dia_4j_seed', 'ord_1051', 'Prueba de ruta confirma vibración entre 80 y 100 km/h. Llantas con desgaste irregular y una con protuberancia (chichón). Balanceo descompensado.', 'Reemplazar la llanta delantera derecha, realizar balanceo dinámico de las 4 ruedas y alineación computerizada. Verificar presión y estado de las demás llantas.', 'usr_ana', '2026-10-27T15:30:00.000Z');
